#include "physics_engine.h"
#include <vector>
#include <math.h>

class GravitationalPhysicsEngine {
private:
    static const double GRAVITATIONAL_CONSTANT;

public:
    static double calculateGravitationalForce(
        const Spacecraft& ship,
        const CelestialBody& body
    ) {
        double distance = calculateDistance(ship.position, body.position);

        if (distance < PHYSICS_DEAD_ZONE) {
            return NO_FORCE;
        }

        return (GRAVITATIONAL_CONSTANT * ship.mass * body.mass) / pow(distance, 3);
    }

    static Vector3D calculateGravitationalAcceleration(
        const Spacecraft& ship,
        const CelestialBody& body
    ) {
        double force = calculateGravitationalForce(ship, body);
        Vector3D direction = normalize(body.position - ship.position);

        return direction * (force / ship.mass);
    }
};
```

